@push('scripts')<script>const form=document.querySelector('form[action="{{ route('pos.returns.store') }}"]');document.querySelector('[data-select-all]')?.addEventListener('click',()=>document.querySelectorAll('[data-return-quantity]').forEach((field)=>field.value=field.dataset.max));document.querySelector('[data-preview-return]')?.addEventListener('click',async()=>{const button=document.querySelector('[data-preview-return]'),preview=document.querySelector('[data-return-preview]');button.disabled=true;button.textContent='Calculating...';try{const response=await fetch('{{ route('pos.returns.preview') }}',{method:'POST',headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:new FormData(form)});const data=await response.json();if(!response.ok)throw new Error(Object.values(data.errors||{}).flat()[0]||'Preview unavailable');preview.innerHTML=`<div><dt class="text-slate-500">Refund</dt><dd class="mt-1 font-semibold text-slate-900">${data.refund_total.toFixed(2)}</dd></div><div><dt class="text-slate-500">Tax adjustment</dt><dd class="mt-1 font-semibold text-slate-900">${data.tax_adjustment.toFixed(2)}</dd></div><div><dt class="text-slate-500">Taxable adjustment</dt><dd class="mt-1 font-semibold text-slate-900">${data.taxable_adjustment.toFixed(2)}</dd></div><div><dt class="text-slate-500">Discount adjustment</dt><dd class="mt-1 font-semibold text-slate-900">${data.discount_adjustment.toFixed(2)}</dd></div>`;}catch(error){preview.innerHTML=`<p class="text-rose-700">${error.message}</p>`;}finally{button.disabled=false;button.textContent='Preview amounts';}});</script>@endpush
